local config = {
  ui_story_31550401_1_dialog_content = "\"The blade of my sword shines clear and bright, like moonlight lacerating the gloom.\"",
  ui_story_31550401_2_dialog_content = "\"Now it is dulled by anger and tarnished by bewilderment.\"",
  ui_story_31550401_3_dialog_content = "\"It is suffering, helpless, lonely, and indignant.\"",
  ui_story_31550401_4_dialog_content = "\"It calls out to me in a voice tinged with bloodlust, yearning for me to become king.\"",
  ui_story_31550401_5_dialog_content = "Barton seems... rather odd these days.",
  ui_story_31550401_6_dialog_content = "What does he want from me?",
  ui_story_31550401_7_dialog_content = "Huff, puff...",
  ui_story_31550401_8_dialog_content = "You're here!",
  ui_story_31550401_9_dialog_content = "But you're far too slow!",
  ui_story_31550401_10_dialog_content = "Regardless of what you're doing, you should run as fast as possible to the assembly point after hearing the assembly call!",
  ui_story_31550401_11_dialog_content = "You hear that, weakling?",
  ui_story_31550401_12_dialog_content = "Yes, Legion Commander!",
  ui_story_31550401_13_dialog_content = "Wait a minute... We were just chatting over the terminal, that's not an assembly call!",
  ui_story_31550401_14_dialog_content = "You have a point.",
  ui_story_31550401_15_dialog_content = "Then replace the sound of the Fireflies with that of the Illumina bugles.",
  ui_story_31550401_16_dialog_content = "Sound the bugles every day to ensure everyone adheres strictly to the rules of the barracks!",
  ui_story_31550401_17_option_content = "Forgive me, but I refuse!",
  ui_story_31550401_18_dialog_content = "Please don't do that! This is the Colossus, not the barracks!",
  ui_story_31550401_19_dialog_content = "As I recall, I'm not an Illumina soldier either!",
  ui_story_31550401_20_option_content = "Let's see...",
  ui_story_31550401_21_dialog_content = "If I really do change it... I'll be woken up by the bugles every day.",
  ui_story_31550401_22_dialog_content = "It'll surely dampen my mood for the day!",
  ui_story_31550401_23_dialog_content = "Absolutely not! Please stay away from the Fireflies!",
  ui_story_31550401_24_dialog_content = "Heheh... I see, you're still adept at specious arguments as always, huh, Caelestite weakling.",
  ui_story_31550401_25_dialog_content = "No way... Forget it. I'll just take it as a compliment.",
  ui_story_31550401_26_dialog_content = "Excellent. I do admire that calm composure of yours.",
  ui_story_31550401_27_dialog_content = "Enough idle chitchat. How about a round of wargame?",
  ui_story_31550401_28_dialog_content = "...",
  ui_story_31550401_29_dialog_content = "(I won't lose so easily! Not this time!)",
  ui_story_31550401_30_dialog_content = "(I've even surreptitiously practiced hard for a long time... and even asked Carleen and the others for help...)",
  ui_story_31550401_31_dialog_content = "(Show me, Barton! How are you going to counter this?!)",
  ui_story_31550401_32_dialog_content = "<color=#e8d9bb>Clack</color>",
  ui_story_31550401_33_dialog_content = "Interesting, but it's useless!",
  ui_story_31550401_34_dialog_content = "<color=#e8d9bb>Clack</color>",
  ui_story_31550401_35_dialog_content = "What?! My perfect setup got destroyed so instantaneously!",
  ui_story_31550401_36_dialog_content = "Hmph, this is merely a trick you've picked up from the Lumopolis chess players.",
  ui_story_31550401_37_dialog_content = "Although it may seem impeccable on the surface, it's teeming with faults.",
  ui_story_31550401_38_dialog_content = "All I have to do is mislead you a little, and you fall right into my trap.",
  ui_story_31550401_39_dialog_content = "You're still far too inexperienced to have pulled this sort of trick on a seasoned chess player!",
  ui_story_31550401_40_dialog_content = "Come on, make your move!",
  ui_story_31550401_41_dialog_content = "Your king shall fall within three moves!",
  ui_story_31550401_42_dialog_content = "I-I'll never admit defeat!",
  ui_story_31550401_43_dialog_content = "<color=#e8d9bb>Clack</color>",
  ui_story_31550401_44_dialog_content = "I'm sorry... I've lost.",
  ui_story_31550401_45_dialog_content = "But it's not over yet! Let's play another round!",
  ui_story_31550401_46_dialog_content = "Hahaha, you've got some guts!",
  ui_story_31550401_47_dialog_content = "(No... Barton's attack is so fast and aggressive that he's not giving me any chance to catch my breath and think.)",
  ui_story_31550401_48_dialog_content = "(He seems even stronger than before. Could it be that the Chord Link has enhanced his mind?!)",
  ui_story_31550401_49_dialog_content = "(All I can do now is take my chances and see how it goes from here...)",
  ui_story_31550401_50_dialog_content = "<color=#e8d9bb>Clack</color>",
  ui_story_31550401_51_dialog_content = "...",
  ui_story_31550401_52_dialog_content = "<color=#e8d9bb>Clack</color>",
  ui_story_31550401_53_dialog_content = "...!",
  ui_story_31550401_54_dialog_content = "Huh?",
  ui_story_31550401_55_dialog_content = "(I've actually found an opening! In that case, I'm not going to hold back!)",
  ui_story_31550401_56_dialog_content = "12 losses, 0 wins, and 1 tie...",
  ui_story_31550401_57_dialog_content = "Hahaha! Not bad, weakling.",
  ui_story_31550401_58_dialog_content = "At the very least, you've managed to play to a draw in one game. You've improved really quickly!",
  ui_story_31550401_59_dialog_content = "The draw... It's only because you've made a mistake, right?",
  ui_story_31550401_60_dialog_content = "Honestly speaking... You were scaring me when we were playing chess earlier.",
  ui_story_31550401_61_dialog_content = "It was as though... I could sense your intent to kill me during the game.",
  ui_story_31550401_62_dialog_content = "Hmph... Caelestites sure are perceptive, aren't they?",
  ui_story_31550401_63_dialog_content = "I did cave into foolish impulses and make a wrong move.",
  ui_story_31550401_64_dialog_content = "I'll admit that I also believe there are some problems within myself.",
  ui_story_31550401_65_dialog_content = "Even though that stupid device has enhanced my power, it also seems as though it has taken something from me.",
  ui_story_31550401_66_dialog_content = "There are even times when my consciousness is in disarray, just like how I made an elementary mistake earlier.",
  ui_story_31550401_67_dialog_content = "What's more, my wrath and resentment for losing to that person... has always been keeping the fire in my heart ablaze.",
  ui_story_31550401_68_dialog_content = "Barton...",
  ui_story_31550401_69_dialog_content = "If this is the price to pay for becoming stronger, I'm willing to be torn apart.",
  ui_story_31550401_70_dialog_content = "You know... Perhaps, there's something I can give you a hand?",
  ui_story_31550401_71_dialog_content = "That won't be necessary. Little weaklings, like you, would be of no help.",
  ui_story_31550401_72_dialog_content = "A pawn can never ascend to the throne by relying on external forces alone.",
  ui_story_31550401_73_dialog_content = "I appreciate the thought, but I'll come up with something myself. Let's go, Sergeants.",
  ui_story_31550401_74_dialog_content = "*Howling*",
  ui_story_31550401_75_dialog_content = "Just wait until you see an immeasurably formidable Legion Commander!",
  ui_story_31550401_76_dialog_content = "Hahahahaha!",
  ui_story_31550401_77_dialog_content = "Hmm? When did those two dogs get here? Wait, did he just take off with the dogs?",
  ui_story_31550401_78_dialog_content = "I just can't help feeling worried...",
  ui_story_31550401_79_dialog_content = "We're here, Sergeants.",
  ui_story_31550401_80_dialog_content = "Awoo!",
  ui_story_31550401_81_dialog_content = "You should still remember this place since it's where I promoted you to Sergeant.",
  ui_story_31550401_82_dialog_content = "Ooowooooooooo!",
  ui_story_31550401_83_dialog_content = "Not bad! That's a nice and clear barking!",
  ui_story_31550401_84_dialog_content = "Now that the little boat has sunk, I'll end this on my own, with you two as my witnesses!",
  ui_story_31550401_85_dialog_content = "Awoo!",
  ui_story_31550401_86_dialog_content = "To face this terrifying sea once more...",
  ui_story_31550401_87_dialog_content = "The piercingly cold seawater...",
  ui_story_31550401_88_dialog_content = "It's as if it is trying to rip my skin apart and invade my body...",
  ui_story_31550401_89_dialog_content = "The water level has reached my chest... It's becoming more difficult to move my limbs and breathe.",
  ui_story_31550401_90_dialog_content = "The sea seems to be trying to restrain me... or hug me.",
  ui_story_31550401_91_dialog_content = "Just like that newfound power... and the surging resentment that comes with a roar.",
  ui_story_31550401_92_dialog_content = "I, Barton... will never lose to you.",
  ui_story_31550401_93_dialog_content = "Yes... That's it. Use your entire body to embrace the power... as well as the fear.",
  ui_story_31550401_94_dialog_content = "...",
  ui_story_31550401_95_dialog_content = "...!",
  ui_story_31550401_96_dialog_content = "Bloody hell... I've failed.",
  ui_story_31550401_97_dialog_content = "It'd be useless to blow the sea to bits... since the water'll just converge into the sea again.",
  ui_story_31550401_98_dialog_content = "... I'll get some rest first, so please stand watch over me, Sergeants.",
  ui_story_31550401_99_dialog_content = "Awoo!",
  ui_story_31550401_100_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_101_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31550401_102_dialog_content = "\"I've indeed undergone some changes.\"",
  ui_story_31550401_103_dialog_content = "\"But I know that some things can't be changed...\"",
  ui_story_31550401_104_dialog_content = "Barton...",
  ui_story_31550401_105_dialog_content = "Barton... What are you hesitating over?",
  ui_story_31550401_106_dialog_content = "O-Officer Pango?!",
  ui_story_31550401_107_dialog_content = "Why are you here?! Aren't you...",
  ui_story_31550401_108_dialog_content = "What are you trying to say? Gosh, look at that unsightly face of yours!",
  ui_story_31550401_109_dialog_content = "And you call yourself a soldier?",
  ui_story_31550401_110_dialog_content = "I'm sorry, sir... But I...",
  ui_story_31550401_111_dialog_content = "No ifs or buts! You'll have to remember who you are well!",
  ui_story_31550401_112_dialog_content = "Let me ask you this: Can you still recall where your loyalties lie?",
  ui_story_31550401_113_dialog_content = "Of course, I'm the sword and shield of Illumina!",
  ui_story_31550401_114_dialog_content = "Good. Then, what's glory to you?",
  ui_story_31550401_115_dialog_content = "It is our honor to expel the Eclipsites and protect all Aurorians!",
  ui_story_31550401_116_dialog_content = "Excellent! What do you fight for?",
  ui_story_31550401_117_dialog_content = "Splendor Illumina!",
  ui_story_31550401_118_dialog_content = "Speak up, I can't hear you!!",
  ui_story_31550401_119_dialog_content = "Splendor Illumina!!!",
  ui_story_31550401_120_dialog_content = "Excellent!!",
  ui_story_31550401_121_dialog_content = "Don't you already know this?",
  ui_story_31550401_122_dialog_content = "You are a fighter, a soldier!",
  ui_story_31550401_123_dialog_content = "You're surrounded by countless comrades-in-arms who share the same interests and beliefs!",
  ui_story_31550401_124_dialog_content = "Yet, not only do you now fear the formidable power, but you're also afraid of losing control over it and putting them in harm's way?",
  ui_story_31550401_125_dialog_content = "Yes...",
  ui_story_31550401_126_dialog_content = "That's absurd! Attention!",
  ui_story_31550401_127_dialog_content = "Yes, sir!",
  ui_story_31550401_128_dialog_content = "Do you think you're the only one who can become a king, Little Barton?",
  ui_story_31550401_129_dialog_content = "Come, Soldier, tell me how does one become a king?",
  ui_story_31550401_130_dialog_content = "With unswerving determination, you have to deplete all of your blood and sweat to accumulate sufficient power!",
  ui_story_31550401_131_dialog_content = "That's right! If you're able to become a king, your comrades-in-arms will also possess the same power as well!",
  ui_story_31550401_132_dialog_content = "Even if you do lose control and become a \"mad king,\" they'll still possess the power to put you on the right path!",
  ui_story_31550401_133_dialog_content = "Yes, sir!",
  ui_story_31550401_134_dialog_content = "Get this into your head...",
  ui_story_31550401_135_dialog_content = "Never let your comrades down, much less underestimate them!",
  ui_story_31550401_136_dialog_content = "Yes, sir!!",
  ui_story_31550401_137_dialog_content = "All right, then. Go on and embrace your power that'll open up a brand new path.",
  ui_story_31550401_138_dialog_content = "Never let our blood be spilt in vain!",
  ui_story_31550401_139_dialog_content = "That's an order!",
  ui_story_31550401_140_dialog_content = "Yes, Officer Pango!!",
  ui_story_31550401_141_dialog_content = "Whoa!!",
  ui_story_31550401_142_dialog_content = "Awoo!!",
  ui_story_31550401_143_dialog_content = "He's finally up. Did I not tell you that he's going to be fine?",
  ui_story_31550401_144_dialog_content = "If the awe-inspiring Legion Commander Barton were to drown in a wilderness like this,",
  ui_story_31550401_145_dialog_content = "Illumina will surely fall into disgrace, like Lumopolis.",
  ui_story_31550401_146_dialog_content = "Are you alright, Barton?",
  ui_story_31550401_147_dialog_content = "Yes, I'm fine... Why's everyone here?",
  ui_story_31550401_148_dialog_content = "Well... Aren't you here to learn swimming?",
  ui_story_31550401_149_dialog_content = "Everyone's pretty worried about you after pulling a disappearing act for so long without saying anything.",
  ui_story_31550401_150_dialog_content = "Ahem, worry my a... I'm fine.",
  ui_story_31550401_151_dialog_content = "Even if he isn't able to pick up swimming, I'm sure he can return by digging a tunnel back or something. I mean, he's Barton, after all.",
  ui_story_31550401_152_dialog_content = "Hahaha, you got that right!",
  ui_story_31550401_153_dialog_content = "Since we're all here, no one's allowed to leave today. Come on, let's have a swimming training session together!",
  ui_story_31550401_154_dialog_content = "For the sake of being ready for any possible enemies from the sea...",
  ui_story_31550401_155_dialog_content = "We, Legion Commanders, must take the lead in learning to swim properly!",
  ui_story_31550401_156_dialog_content = "That's interesting. Come on, let's see who's the best then.",
  ui_story_31550401_157_dialog_content = "Eh? But I didn't bring a swimsuit...",
  ui_story_31550401_158_dialog_content = "Let's go. It's been ages since I last tried water sports.",
  ui_story_31550401_159_dialog_content = "They just... ran off to swim just like that...",
  ui_story_31550401_160_dialog_content = "Anyways, all that matters is that Barton is fine and looks far more energetic now.",
  ui_story_31550401_161_dialog_content = "However, I wonder who's the \"Officer Pango\" that he kept shouting for in his sleep...",
  ui_story_31550401_162_dialog_content = "The name sounds rather familiar, though...",
  ui_story_31550601_1_dialog_content = "Ha, I knew you'd come, PlayerName!",
  ui_story_31550601_2_dialog_content = "Only because your message sounded so urgent, Barton...",
  ui_story_31550601_3_dialog_content = "That's because it is urgent! My old commanding officer's finally awake again!",
  ui_story_31550601_4_dialog_content = "This is some of the best news I've gotten in my life, and you're the first person I wanted to share it with.",
  ui_story_31550601_5_dialog_content = "And, uh... Since you're here, would you mind using your powers to check on Officer Pango's mental state? Much obliged!",
  ui_story_31550601_6_dialog_content = "So that's why you called me over!",
  ui_story_31550601_7_dialog_content = "Huh? Now that I think about it, you're not wearing this outfit because—",
  ui_story_31550601_8_dialog_content = "That's right. I'm worried the commander might not recognize me, so I dug up this old number.",
  ui_story_31550601_9_dialog_content = "He got knocked into a coma while defending Gannon City from Eclipsites. That battle took place over ten years ago.",
  ui_story_31550601_10_dialog_content = "In that time, I've gone from an obnoxious punk of a recruit to the fine commander you see today! That's why I worry he won't recognize me right away.",
  ui_story_31550601_11_dialog_content = "I doubt it. You're still Barton, after all.",
  ui_story_31550601_12_dialog_content = "I've tried so hard to have conversations with him all these years, hoping it would wake him up someday...",
  ui_story_31550601_13_dialog_content = "When I suddenly got the call, I was at a loss for words.",
  ui_story_31550601_14_dialog_content = "Anyway, I'm grateful that you came. Come on, let's go in.",
  ui_story_31550601_15_dialog_content = "... Stop all that poking and prodding, dammit! I'm perfectly aware of my own body, thank you very much!",
  ui_story_31550601_16_dialog_content = "Now let me go, you idiots! The fight's not over yet!",
  ui_story_31550601_17_dialog_content = "Barton?",
  ui_story_31550601_18_dialog_content = "Commander Barton!",
  ui_story_31550601_19_dialog_content = "Officer Pango... You're really awake...",
  ui_story_31550601_20_dialog_content = "... Why on earth are you wearing such a stupid-looking thing? Never mind, you came at just the right time—tell them to let me go already.",
  ui_story_31550601_21_dialog_content = "They're keeping me trapped in here, saying it's for my own good or some nonsense like that.",
  ui_story_31550601_22_dialog_content = "They're also telling me that the Darkover Crisis ended over ten years ago! Can you believe that?",
  ui_story_31550601_23_dialog_content = "The frontlines are in serious danger. Gannon City has been completely surrounded...",
  ui_story_31550601_24_dialog_content = "Wait... Barton... When did you start growing gray hair?",
  ui_story_31550601_25_dialog_content = "Officer Pango... The battle ended a long time ago.",
  ui_story_31550601_26_dialog_content = "... You're spouting off the same nonsense too? What the hell is going on here?",
  ui_story_31550601_27_dialog_content = "And who's that weak-looking new recruit? Did Illumina lower its enlistment standards again?",
  ui_story_31550601_28_dialog_content = "Hello, sir. Actually, I'm—",
  ui_story_31550601_29_dialog_content = "I need to return to battle, now make it happen! That's an order, Barton!",
  ui_story_31550601_30_dialog_content = "I'm sick of all these bandages and needles! Send me back to the battlefront, so I can get some fresh air!",
  ui_story_31550601_31_dialog_content = "I'm sure everything will make sense once I go back there...",
  ui_story_31550601_32_dialog_content = "Yes, sir!",
  ui_story_31550601_33_dialog_content = "What do you think about Officer Pango's recovery, PlayerName? Is his mental state... normal?",
  ui_story_31550601_34_option_content = "Sense Pango",
  ui_story_31550601_35_dialog_content = "Hang on... What is this feeling?",
  ui_story_31550601_36_dialog_content = "He's perfectly fine... He's just having a hard time believing what other people say, that's all.",
  ui_story_31550601_37_dialog_content = "Thanks... Let's go, sir. It's not easy for you to move around right now, but that's what these wheelchairs are for.",
  ui_story_31550601_38_dialog_content = "What is this, Barton? Why did you bring me to a museum?",
  ui_story_31550601_39_dialog_content = "I'm sure they told you everything when you first woke up, Officer Pango.",
  ui_story_31550601_40_dialog_content = "You were in a coma for over a decade. The Darkover Crisis ended a long time ago as well.",
  ui_story_31550601_41_dialog_content = "As you can see, your worthless old subordinate is now the commander of the 2nd Legion.",
  ui_story_31550601_42_dialog_content = "This is... My dog tag?",
  ui_story_31550601_43_dialog_content = "That's right, sir. You left this with me all those years ago.",
  ui_story_31550601_44_dialog_content = "Do you still remember that day? Toward the end of the crisis, you told us all to retreat, but you stayed to fight.",
  ui_story_31550601_45_dialog_content = "We're all safe now, sir. Everything that happened is in the past now.",
  ui_story_31550601_46_dialog_content = "Impossible...",
  ui_story_31550601_47_dialog_content = "And now, let us turn our attention to the valiant efforts of the 2nd Legion's Machine Division during the Darkover Crisis.",
  ui_story_31550601_48_dialog_content = "!",
  ui_story_31550601_49_dialog_content = "As you've all read before, even Gannon City fell to Eclipsite incursion at the height of the Darkover Crisis.",
  ui_story_31550601_50_dialog_content = "In order to facilitate the city's evacuation, every member of the 2nd Legion stayed behind to continue battling the enemy.",
  ui_story_31550601_51_dialog_content = "The tank you see before you is an Illumina Model L3, and this particular one was operated by the 2nd Legion during that battle.",
  ui_story_31550601_52_dialog_content = "Wow—",
  ui_story_31550601_53_dialog_content = "That's our tank, Barton... What happened to it? Why is it... all busted up?",
  ui_story_31550601_54_dialog_content = "Because it gave everything it had to save Gannon City, sir, just like you.",
  ui_story_31550601_55_dialog_content = "In spite of its damage, it still hasn't retired. It lives on in this museum to teach and inspire future generations.",
  ui_story_31550601_56_dialog_content = "This tank is an immortal veteran of the 2nd Legion.",
  ui_story_31550601_57_dialog_content = "Commander Barton? We weren't expecting you today, sir. Pardon me, but your guest...",
  ui_story_31550601_58_dialog_content = "Is it... Is it really you? The legendary guardian of the Central Tower?",
  ui_story_31550601_59_dialog_content = "It really is you! You're finally awake, Commander Pango!",
  ui_story_31550601_60_dialog_content = "What? He actually woke up from his coma?",
  ui_story_31550601_61_dialog_content = "Pango? You mean the legendary commander who led a troop of veterans to defend the Central Tower? Where?",
  ui_story_31550601_62_dialog_content = "Officer Pango! Are you sure you should be moving right now? We want to train under you, sir!",
  ui_story_31550601_63_dialog_content = "Hey! Show the officer some respect, you hooligans! If you want to ask questions, ask them one at a time!",
  ui_story_31550601_64_dialog_content = "Yes, sir!",
  ui_story_31550601_65_dialog_content = "Officer Pango! You don't know me, but I hail from the new Undercity 13.",
  ui_story_31550601_66_dialog_content = "If it hadn't been for you and Commander Wrath, Undercity 13 would have been completely annihilated.",
  ui_story_31550601_67_dialog_content = "So thank you... Thank you for saving us, and for giving us a chance to rebuild our home.",
  ui_story_31550601_68_dialog_content = "The \"new\" Undercity 13?",
  ui_story_31550601_69_dialog_content = "My turn! Greetings, Officer Pango! I was born and raised in one of Gannon City's oldest districts.",
  ui_story_31550601_70_dialog_content = "Thanks to your bravery, my entire family was kept safe from Eclipsites.",
  ui_story_31550601_71_dialog_content = "I was only a kid when we retook the city, but I enlisted as soon as I came of age! My dream is to become a hero just like you, sir!",
  ui_story_31550601_72_dialog_content = "\"Retook the city\"...",
  ui_story_31550601_73_dialog_content = "Alright, that's enough for now. Give the officer some space.",
  ui_story_31550601_74_dialog_content = "Hmm? Well, if it isn't our dear comrade, the Caelestite! Welcome back to Illumina, my friend.",
  ui_story_31550601_75_dialog_content = "Pleasure to be back!",
  ui_story_31550601_76_dialog_content = "You're a Caelestite? But during the Darkover Crisis, Eraveil had already...",
  ui_story_31550601_77_dialog_content = "... I know. The truth is, I'm—",
  ui_story_31550601_78_dialog_content = "PlayerName was lucky enough to survive the attack on Eraveil! Something tells me there are plenty of other Caelestites waiting for him out there!",
  ui_story_31550601_79_dialog_content = "Lots of things have gotten better in the years since the Darkover Crisis, sir.",
  ui_story_31550601_80_dialog_content = "So we really won? Is Astra really at peace again?",
  ui_story_31550601_81_dialog_content = "Yes, sir. We won... While the peace we secured isn't perfect, we managed to survive the Darkover Crisis.",
  ui_story_31550601_82_dialog_content = "Undercity 13 was rebuilt, along with Gannon City. Our future generations are no longer being raised in the trenches of war.",
  ui_story_31550601_83_dialog_content = "... I saw myself in the mirror when I woke up this morning.",
  ui_story_31550601_84_dialog_content = "All that white hair on my head... I guess it wasn't from my injuries at all.",
  ui_story_31550601_85_dialog_content = "Still, time seems to have healed many things as well.",
  ui_story_31550601_86_dialog_content = "Even though... I lost so much time myself...",
  ui_story_31550601_87_dialog_content = "You've gotten so mature in what feels like the blink of an eye, Barton.",
  ui_story_31550601_88_dialog_content = "Your training is what shaped me into a pillar of the Illumina Federation, sir.",
  ui_story_31550601_89_dialog_content = "I know exactly what my duties are, and I lead our soldiers forward without any doubt in my heart. The 2nd Legion is in good hands, so please focus on resting and recovering, sir.",
  ui_story_31550601_90_dialog_content = "... Heh. The Barton I knew wouldn't talk like that at all.",
  ui_story_31550601_91_dialog_content = "Take me to see the monument, would you?",
  ui_story_31550601_92_dialog_content = "Yes, sir.",
  ui_story_31550601_93_dialog_content = "I want to see how the 2nd Legion is doing now as well.",
  ui_story_31550601_94_dialog_content = "Someone has to make sure you haven't screwed everything up, after all.",
  ui_story_31550601_95_dialog_content = "If I find out you were blowing a bunch of hot air just now, I'm putting you through the same brutal training as I did before!",
  ui_story_31550601_96_dialog_content = "Understood, sir!",
  ui_story_31550601_97_dialog_content = "Er, Officer Pango...",
  ui_story_31550601_98_dialog_content = "What is it?",
  ui_story_31550601_99_dialog_content = "It's been an honor to meet you, as well as Commander Barton and the Caelestite.",
  ui_story_31550601_100_dialog_content = "You've sacrificed so much to aid us, and to aid all of Astra.",
  ui_story_31550601_101_dialog_content = "Would it be okay if we... took a picture to commemorate this day? Please?",
  ui_story_31550601_102_dialog_content = "Sure.",
  ui_story_31550601_103_dialog_content = "Ha! Get over here, PlayerName! You don't get a chance like this all the time, so squeeze in!",
  ui_story_31550601_104_dialog_content = "A group photo with two legendary war heroes? Not gonna lie, I'm a little nervous...",
  ui_story_31550601_105_dialog_content = "You'll get over it! Besides, you're an important ally in the struggle too!",
  ui_story_31550601_106_dialog_content = "Everybody ready? Good! Now look into the camera and repeat after me—Splendor Illumina!",
  ui_story_31550601_107_dialog_content = "Splendor Illumina!",
  ui_story_31550601_108_dialog_content = "It's ready! Come look!",
  ui_story_31550601_109_dialog_content = "I still look really nervous...",
  ui_story_31550601_110_dialog_content = "Heheh, and I'm as photogenic as ever!",
  ui_story_31550601_111_dialog_content = "...",
  ui_story_31550601_112_dialog_content = "I remember taking a photo like this before...",
  ui_story_31550601_113_dialog_content = "Ah! That's right... Our old group photo...",
  ui_story_31550601_114_dialog_content = "Alright, now everyone smile big this time—Splendor Illumina!",
  ui_story_31550601_115_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_31550601_116_dialog_content = "The kids of the 2nd Legion...",
  ui_story_31550601_117_dialog_content = "Have you become the stars that light others' paths?"
}
return config
